param([string]$MigrationPath,[switch]$VerifyLiveData)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/stromkar-ritual-beam"
if(!$MigrationPath){$MigrationPath="$repo/sql/updates/world/2026_10_28_04_stromkar_ritual_receiver.sql"}
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -Test {
 $migration=[IO.File]::ReadAllText($MigrationPath);$hash=[Security.Cryptography.SHA1]::Create();try{$sha=[BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($migration.Replace("`r`n","`n")))).Replace("-","")}finally{$hash.Dispose()}
 $connection=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$connection[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($connection[0]) --port=$($connection[1]) --user=$($connection[2]) --database=$($connection[4]) --batch --raw --skip-column-names);if($LASTEXITCODE){throw 'Ritual TEMP/read failed'};$rows}finally{$env:MYSQL_PWD=$prior}}
 $sql='';$reset='';foreach($table in @('creature_template','creature','smart_scripts','spell_script_names')){$filter=switch($table){creature_template{'entry=101875'}creature{'guid IN(370922,370936,370937,370943)'}smart_scripts{'entryorguid=101875'}spell_script_names{'spell_id=201031'}};$sql+="CREATE TEMPORARY TABLE saved_$table LIKE $table;INSERT INTO saved_$table SELECT * FROM $table WHERE $filter;CREATE TEMPORARY TABLE $table LIKE saved_$table;`n";$reset+="DELETE FROM $table;INSERT INTO $table SELECT * FROM saved_$table;`n"}
 if($VerifyLiveData){$sql+="SET @released:=EXISTS(SELECT 1 FROM updates WHERE name='2026_10_28_04_stromkar_ritual_receiver.sql' AND hash='$sha' AND state='RELEASED');UPDATE saved_smart_scripts SET event_type=60,event_flags=1,event_param3=0,event_param4=0 WHERE id=6 AND source_type=0 AND event_type=1 AND event_flags=0 AND event_param3=1000 AND event_param4=1000 AND @released;DELETE FROM saved_spell_script_names WHERE ScriptName='spell_stromkar_ritual_beam' AND @released;`n"}
 $snapshot="SELECT 'TAG-smart',smart_scripts.* FROM smart_scripts ORDER BY source_type,id;SELECT 'TAG-script',spell_script_names.* FROM spell_script_names ORDER BY spell_id,ScriptName;"
 $sql+="$reset$migration`n$($snapshot.Replace('TAG','first'))`n$migration`n$($snapshot.Replace('TAG','second'))`nSELECT 'fixed',event_type,event_flags,event_param3,event_param4,action_param2 FROM smart_scripts WHERE source_type=0 AND id=6;SELECT 'binding',ScriptName FROM spell_script_names WHERE spell_id=201031;"
 $variants=@("UPDATE creature_template SET ScriptName='custom';","UPDATE smart_scripts SET action_param1=1 WHERE id=6;","UPDATE smart_scripts SET target_param1=1 WHERE id=6;","UPDATE smart_scripts SET action_param2=1 WHERE id=6;","DELETE FROM creature WHERE guid=370922;","UPDATE creature SET PhaseId='5737' WHERE guid=370936;","INSERT INTO spell_script_names VALUES(201031,'custom');")
 $i=0;foreach($variant in $variants){$sql+="$reset$variant`n$($snapshot.Replace('TAG',"v$i-before"))`n$migration`n$($snapshot.Replace('TAG',"v$i-after"))`n";++$i}
 $rows=Query $sql;[IO.File]::WriteAllLines("$out/sql-evidence.tsv",[string[]]$rows)
 function Snapshot([string]$prefix){[string]::Join("`n",@($rows|Where-Object {$_ -like "$prefix*"}|ForEach-Object {$_.Substring($prefix.Length)}))}
 if((Snapshot 'first') -cne (Snapshot 'second')){throw 'Migration not idempotent'}
 for($i=0;$i -lt $variants.Count;++$i){if((Snapshot "v$i-before") -cne (Snapshot "v$i-after")){throw "Modified custom variant$i"}}
 if($rows -notcontains "fixed`t1`t0`t1000`t1000`t0" -or $rows -notcontains "binding`tspell_stromkar_ritual_beam"){throw 'Binding/retry missing'}
 $source=[IO.File]::ReadAllText("$repo/src/server/game/Spells/Spell.cpp");if($source.IndexOf('    HandleLaunchPhase();') -ge $source.IndexOf('    SendSpellGo();')){throw 'Launch no longer precedes outbound visual'}
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncd /d `"$out`"`ncl /nologo /EHsc /std:c++17 /fsanitize=address /Zi `"$PSScriptRoot/StromkarRitualBeamTest.cpp`" /Fe:test.exe /Fo:test.obj`nif errorlevel 1 exit /b 1`ntest.exe`nexit /b %errorlevel%`n")
 & "$out/run.cmd";if($LASTEXITCODE){throw 'Actual ritual script regression failed'}
 if($VerifyLiveData){$live=Query "SELECT 'release',hash,state FROM updates WHERE name='2026_10_28_04_stromkar_ritual_receiver.sql';SELECT 'fixed',event_type,event_flags,event_param3,event_param4,action_param2 FROM smart_scripts WHERE entryorguid=101875 AND source_type=0 AND id=6;SELECT 'binding',ScriptName FROM spell_script_names WHERE spell_id=201031;";foreach($expected in @("release`t$sha`tRELEASED","fixed`t1`t0`t1000`t1000`t0","binding`tspell_stromkar_ritual_beam")){if($live -notcontains $expected){throw "Live mismatch $expected"}}}
 'PASS guarded ritual receiver TEMP replay twice/seven refusals and ASAN production script. No actual client rendering certification.'
}
